def _get_provider_usage(self, provider):
    return self.api.nodes_cache.getQuota(provider, include_requested=True)

def _get_other_endpoint_usage(self, provider):
    other_endpoint_usage = 0
    for other_provider in self.api.nodes_cache.providers:
        if other_provider != provider:
            other_endpoint_usage += self._get_provider_usage(other_provider)
    return other_endpoint_usage

def _get_provider_limits(self, provider):
    cloud_quota = self.api.nodes_cache.getCloudQuota()
    provider_resource_limits = self.api.nodes_cache.getProviderResourceLimits(provider)
    return min(cloud_quota, provider_resource_limits)

def _get_final_quota(self, provider):
    provider_limits = self._get_provider_limits(provider)
    other_endpoint_usage = self._get_other_endpoint_usage(provider)
    this_provider_usage = self._get_provider_usage(provider)
    return min(provider_limits - other_endpoint_usage - this_provider_usage, provider_limits)
