    def login(self, user, session_id):
        # Log the user login and set the last activity time
        self.sessions[session_id] = {'user': user, 'last_activity': datetime.now()}

    def logout(self, session_id):
        # Remove the session from the dictionary
        if session_id in self.sessions:
            del self.sessions[session_id]

    def check_sessions(self):
        # Check all sessions and logout those that have been inactive for too long
        current_time = datetime.now()
        for session_id, session_info in list(self.sessions.items()):
            if current_time - session_info['last_activity'] > self.timeout:
